void truncate(char* str, int maxlen) {
    if ((int)strlen(str) > maxlen)
        str[maxlen] = '\0';
}

int countVowels(const char* s) {
    int c = 0;
    for (; *s; s++) {
        char ch = tolower((unsigned char)*s);
        if (strchr("aeiouy", ch)) c++;
    }
    return c;
}
